import{V as e,Z as t,et as n,mt as r,nt as i,tt as a}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var o=JSON.parse(`{"title":"Field Settings","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/form-fields/field-settings.md","filePath":"documentation/form-fields/field-settings.md","lastUpdated":1788551488000}`),s={name:`documentation/form-fields/field-settings.md`};function c(e,o,s,c,l,u){return r(),n(`div`,null,[...o[0]||=[a(`<h1 id="field-settings" tabindex="-1">Field Settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to “Field Settings”">​</a></h1><p>Field Settings provide comprehensive configuration options for individual form fields. When you <strong>edit</strong> a field, a sidebar drawer opens displaying all available settings for that specific field. Some settings are tailored to particular <a href="/documentation/form-fields/field-types.html">field types</a>, while others apply across all field types.</p><hr><h2 id="basic-field-settings" tabindex="-1">Basic Field Settings <a class="header-anchor" href="#basic-field-settings" aria-label="Permalink to “Basic Field Settings”">​</a></h2><h3 id="simulate-human-typing-speed" tabindex="-1">Simulate Human Typing Speed <a class="header-anchor" href="#simulate-human-typing-speed" aria-label="Permalink to “Simulate Human Typing Speed”">​</a></h3><p>Enables <strong>human-like typing</strong> behavior in input fields, simulating realistic keystrokes with configurable typing speed.</p><ul><li><strong>Realistic Typing</strong>: Mimics natural human typing cadence instead of instant value assignment.</li><li><strong>Speed Control</strong>: Adjustable delay in milliseconds between keystrokes.</li><li><strong>Character-by-Character</strong>: Types each character sequentially, triggering standard DOM keyboard events.</li><li><strong>Use Cases</strong>: Bypassing anti-bot detection systems and testing client-side form validation rules.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Formerly labeled as &quot;Fill the values like a typing tutor&quot;. <a id="fill-the-values-like-a-typing-tutor"></a></p></div><hr><h3 id="text-editor-mode" tabindex="-1">Text editor mode <a class="header-anchor" href="#text-editor-mode" aria-label="Permalink to “Text editor mode”">​</a></h3><p>A specialized simulation mode designed specifically for rich text editors (such as Quill, TinyMCE, CKEditor, CodeMirror, Slate, Draft.js, or custom <code>contenteditable</code> containers) and complex inputs that require fine-grained keystroke pacing and human pause behaviors.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Min Key Delay (ms)</strong></td><td><code>50</code></td><td>Minimum delay in milliseconds between consecutive key presses.</td></tr><tr><td><strong>Max Key Delay (ms)</strong></td><td><code>120</code></td><td>Maximum delay in milliseconds between consecutive key presses.</td></tr><tr><td><strong>Enable Random Pause</strong></td><td>Toggle (ON/OFF)</td><td>Enables occasional pauses while typing sentences, mirroring human thought pauses.</td></tr><tr><td><strong>Pause Chance (0 to 1)</strong></td><td><code>0.2</code></td><td>Probability of triggering a pause between keystrokes (e.g., <code>0.2</code> = 20% probability).</td></tr><tr><td><strong>Pause Min (ms)</strong></td><td><code>300</code></td><td>Minimum duration of a random pause in milliseconds.</td></tr><tr><td><strong>Pause Max (ms)</strong></td><td><code>600</code></td><td>Maximum duration of a random pause in milliseconds.</td></tr><tr><td><strong>Human Typing</strong></td><td>Toggle (ON/OFF)</td><td>Emits authentic keyboard dispatch cycles (<code>keydown</code>, <code>keypress</code>, <code>keyup</code>, <code>input</code>) for rich editor compatibility.</td></tr></tbody></table><p><strong>Use Cases:</strong></p><ul><li>Populating WYSIWYG editors without losing character sequences or breaking rich text styling.</li><li>Simulating realistic typing cadences to avoid triggering aggressive bot heuristics.</li><li>Ensuring real-time word/character count listeners update accurately.</li></ul><hr><h3 id="before-filling-the-value-in-the-field-clear-the-value-of-the-field" tabindex="-1">Before filling the value in the field, clear the value of the field <a class="header-anchor" href="#before-filling-the-value-in-the-field-clear-the-value-of-the-field" aria-label="Permalink to “Before filling the value in the field, clear the value of the field”">​</a></h3><p>Automatically clears any existing or pre-populated field values before entering new data.</p><ul><li><strong>Clean Slate</strong>: Ensures no residual data or placeholder text remains in the input.</li><li><strong>Data Integrity</strong>: Prevents concatenating new spreadsheet values onto existing text.</li><li><strong>Consistent Results</strong>: Guarantees clean and predictable data entry across repeated runs.</li></ul><hr><h3 id="if-excel-column-value-is-empty-then-fill-this-default-value" tabindex="-1">If excel column value is empty then fill this default value <a class="header-anchor" href="#if-excel-column-value-is-empty-then-fill-this-default-value" aria-label="Permalink to “If excel column value is empty then fill this default value”">​</a></h3><p>Sets a fallback value when the Excel column cell is empty or missing data.</p><ul><li><strong>Default Value</strong>: Specify the fallback string, number, or predefined variable to enter.</li><li><strong>Visual Indicator</strong>: <ul><li>Green Edit Button: Default value is active and configured.</li><li>Yellow Edit Button: No fallback value configured.</li></ul></li><li><strong>Site-Wide Override</strong>: Can be disabled globally by toggling <code>Ignore field default value</code> in <a href="/documentation/site/site-settings.html#site-configuration-toggles">Site Settings</a>.</li></ul><img src="/image/field-settings-02.png" alt="Field Default Value" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h3 id="take-the-value-of-this-field-from-another-excel-column" tabindex="-1">Take the value of this field from another excel column <a class="header-anchor" href="#take-the-value-of-this-field-from-another-excel-column" aria-label="Permalink to “Take the value of this field from another excel column”">​</a></h3><p>Links the field&#39;s data value to a different Excel column in your <code>.xlsx</code> worksheet, eliminating duplicate columns.</p><ul><li><strong>Data Consistency</strong>: Maintain a single column in your spreadsheet (e.g., <code>Full Name</code>) and reference it across multiple form fields.</li><li><strong>Reduced Redundancy</strong>: Avoid creating duplicate columns with identical data in your Excel file.</li><li><strong>Centralized Updates</strong>: Changing the value in the master column automatically updates all dependent fields during execution.</li></ul><hr><h2 id="data-processing-settings" tabindex="-1">Data Processing Settings <a class="header-anchor" href="#data-processing-settings" aria-label="Permalink to “Data Processing Settings”">​</a></h2><h3 id="replace-the-field-value-according-to-the-custom-values" tabindex="-1">Replace the field value according to the custom values <a class="header-anchor" href="#replace-the-field-value-according-to-the-custom-values" aria-label="Permalink to “Replace the field value according to the custom values”">​</a></h3><p>Transforms spreadsheet values into target form values using custom replacement mappings.</p><ul><li><strong>Field Value</strong>: The original value present in the Excel spreadsheet row.</li><li><strong>Custom Value</strong>: The replacement value that will actually be filled into the web element.</li><li><strong>Multiple Mappings</strong>: Supports defining multiple substitution pairs (e.g., <code>&quot;Yes/Y&quot;</code> → <code>&quot;0&quot;</code>, <code>&quot;No/N&quot;</code> → <code>&quot;1&quot;</code>).</li></ul><img src="/image/replace-field-value-01.png" alt="Replace Field Value Configuration" style="max-width:480px;border-radius:8px;margin:16px 0;"><p><strong>Excel Template Integration</strong>: Configured custom mappings automatically appear in the <code>Field Custom Values</code> reference column within the <code>HELPING</code> sheet of downloaded Excel templates.</p><img src="/image/field-settings-03.png" alt="Field Custom Values in Helping Sheet" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h3 id="paste-copied-value" tabindex="-1">Paste Copied Value <a class="header-anchor" href="#paste-copied-value" aria-label="Permalink to “Paste Copied Value”">​</a></h3><p>Pastes data previously captured using the <a href="/documentation/field-types/copy.html">Copy Field Type</a>.</p><ul><li><strong>Prerequisites</strong>: A Copy Field must execute earlier in the form or routine.</li><li><strong>Text Transformations</strong>: Apply casing adjustments, whitespace trimming, or substring operations prior to pasting.</li><li><strong>Custom Processing</strong>: Modify the copied buffer dynamically using string functions.</li></ul><img src="/image/field-settings-04.png" alt="Paste Settings Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h2 id="element-detection-settings" tabindex="-1">Element &amp; Detection Settings <a class="header-anchor" href="#element-detection-settings" aria-label="Permalink to “Element &amp; Detection Settings”">​</a></h2><h3 id="selector-query-of-elements-child-element" tabindex="-1">Selector Query of Element&#39;s Child Element <a class="header-anchor" href="#selector-query-of-elements-child-element" aria-label="Permalink to “Selector Query of Element&#39;s Child Element”">​</a></h3><p>Specifies a secondary selector targeting a nested child element located inside the primary field element.</p><ul><li><strong>How It Works</strong>: <ol><li>The extension locates the parent container using the field&#39;s primary CSS Selector or XPath.</li><li>It then evaluates the child query relative to that parent node (equivalent to <code>parent.querySelector(childSelector)</code>).</li></ol></li><li><strong>Benefits</strong>: <ul><li><strong>Component Frameworks</strong>: Target a stable outer wrapper (e.g., <code>.custom-input-wrapper</code> or <code>#billing-address</code>) while directing input actions to an inner <code>&lt;input&gt;</code> or <code>[contenteditable]</code>.</li><li><strong>Table Grids &amp; Lists</strong>: Target a specific row or cell container and dynamically locate the interactive button or input inside.</li><li><strong>Shadow DOM / Web Components</strong>: Bridges container boundaries when standard single selectors fail.</li></ul></li></ul><hr><h3 id="wait-until-element-is-found-in-the-page" tabindex="-1">Wait until element is found in the page <a class="header-anchor" href="#wait-until-element-is-found-in-the-page" aria-label="Permalink to “Wait until element is found in the page”">​</a></h3><p>Pauses automation until the target element is detected in the DOM.</p><ul><li><strong>Dynamic Content</strong>: Ideal for Single Page Applications (SPAs) and elements loaded via asynchronous fetch/XHR requests.</li><li><strong>Page Transitions</strong>: Prevents execution errors caused by interacting before DOM nodes are mounted.</li></ul><hr><h3 id="wait-until-element-is-visible-in-the-page" tabindex="-1">Wait until element is visible in the page <a class="header-anchor" href="#wait-until-element-is-visible-in-the-page" aria-label="Permalink to “Wait until element is visible in the page”">​</a></h3><p>Waits until the target element is both present in the DOM and visibly rendered on screen.</p><ul><li><strong>Visibility Criteria</strong>: Ensures <code>display !== &#39;none&#39;</code>, <code>visibility !== &#39;hidden&#39;</code>, and element dimensions are greater than zero.</li><li><strong>Interaction Readiness</strong>: Guarantees modal dialogs, flyout menus, and animations have finished rendering before attempting clicks or text input.</li></ul><hr><h2 id="javascript-event-settings" tabindex="-1">JavaScript &amp; Mouse Event Settings <a class="header-anchor" href="#javascript-event-settings" aria-label="Permalink to “JavaScript &amp; Mouse Event Settings”">​</a></h2><h3 id="trigger-javascript-event" tabindex="-1">Trigger Javascript Event <a class="header-anchor" href="#trigger-javascript-event" aria-label="Permalink to “Trigger Javascript Event”">​</a></h3><p>Dispatches native JavaScript events on the target element after data is filled.</p><ul><li><strong>Supported Events</strong>: <code>change</code>, <code>focus</code>, <code>blur</code>, <code>input</code>, <code>keydown</code>, <code>keyup</code>, <code>submit</code>.</li><li><strong>Framework Reactivity</strong>: Forces modern reactive frameworks (React, Vue, Angular, Svelte) to recognize programmatic DOM updates and trigger state changes.</li></ul><img src="/image/field-settings-05.png" alt="JavaScript Events Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h3 id="trigger-javascript-mouse-event" tabindex="-1">Trigger Javascript Mouse Event <a class="header-anchor" href="#trigger-javascript-mouse-event" aria-label="Permalink to “Trigger Javascript Mouse Event”">​</a></h3><p>Simulates specialized mouse interaction events on target elements.</p><ul><li><strong>Supported Mouse Events</strong>: <code>click</code>, <code>mousedown</code>, <code>mouseup</code>, <code>mouseenter</code>, <code>mouseleave</code>, <code>mouseover</code>.</li><li><strong>Use Cases</strong>: Useful for custom dropdowns, hover triggers, or custom button elements that rely strictly on mouse listener signatures.</li></ul><img src="/image/field-settings-06.png" alt="Mouse Events Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h2 id="field-chaining-settings" tabindex="-1">Field Chaining Settings <a class="header-anchor" href="#field-chaining-settings" aria-label="Permalink to “Field Chaining Settings”">​</a></h2><h3 id="after-filling-the-data-of-this-field-filling-the-data-of-another-field" tabindex="-1">After filling the data of this field, filling the data of another field <a class="header-anchor" href="#after-filling-the-data-of-this-field-filling-the-data-of-another-field" aria-label="Permalink to “After filling the data of this field, filling the data of another field”">​</a></h3><p>Triggers immediate execution of a designated secondary field as soon as the current field operation finishes.</p><ul><li><strong>Direct Chaining</strong>: Creates an explicit sequence between two fields, bypassing standard queue order.</li><li><strong>Cascading Dropdowns</strong>: When selecting a parent category (e.g., Country) loads child options (e.g., State), chaining immediately executes the child field once the parent updates.</li><li><strong>Search &amp; Select Sequences</strong>: Execute a text search field and immediately trigger the corresponding option-selection field.</li></ul><hr><h2 id="conditional-logic-settings" tabindex="-1">Conditional Logic Settings <a class="header-anchor" href="#conditional-logic-settings" aria-label="Permalink to “Conditional Logic Settings”">​</a></h2><h3 id="skip-field-action-if-any-condition-is-true" tabindex="-1">Skip field action if any condition is true <a class="header-anchor" href="#skip-field-action-if-any-condition-is-true" aria-label="Permalink to “Skip field action if any condition is true”">​</a></h3><p>Skips execution of the field when one or more configured conditions evaluate to true.</p><ul><li><strong>Supported Condition Types</strong>: <ul><li>Element Visibility (Visible / Not Visible)</li><li>Element Existence (Exists in DOM / Does Not Exist)</li><li>Value Matching (Element value matches specific string)</li><li>Text Content Matching (Inner text matches specific criteria)</li><li>Attribute Matching (DOM attribute matches value)</li><li>HTML Matching (Inner HTML matches regex or string)</li><li>Image Filename Matching (Image source name matches criteria)</li></ul></li></ul><img src="/image/field-settings-07.png" alt="Skip Conditions Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h3 id="wait-until-the-response-status-of-the-given-element-change-fields-comes" tabindex="-1">Wait until the response status of the given element change fields comes <a class="header-anchor" href="#wait-until-the-response-status-of-the-given-element-change-fields-comes" aria-label="Permalink to “Wait until the response status of the given element change fields comes”">​</a></h3><p>Holds field execution until a specified <a href="/documentation/field-types/element-change.html">Element Change</a> field resolves.</p><ul><li><strong>Field Reference</strong>: Select the designated Element Change field.</li><li><strong>Status Check</strong>: Evaluates Before Field or After Field status conditions.</li><li><strong>Conditional Flow</strong>: Only proceeds once the element change condition returns success.</li></ul><img src="/image/field-settings-11.png" alt="Element Change Wait Configuration" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h3 id="wait-until-the-response-status-of-the-given-request-monitor-fields-comes" tabindex="-1">Wait until the response status of the given request monitor fields comes <a class="header-anchor" href="#wait-until-the-response-status-of-the-given-request-monitor-fields-comes" aria-label="Permalink to “Wait until the response status of the given request monitor fields comes”">​</a></h3><p>Waits for a network API request tracked by a <a href="/documentation/field-types/request-monitor.html">Request Monitor</a> field to finish.</p><ul><li><strong>API Synchronization</strong>: Ensures asynchronous backend calculations or validation checks complete before filling subsequent inputs.</li><li><strong>Network Verification</strong>: Eliminates race conditions on dynamic forms that perform background verification calls.</li></ul><img src="/image/field-settings-12.png" alt="Request Monitor Wait Configuration" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h3 id="if-element-value-matches-then-fill-the-value-otherwise-skip-the-field" tabindex="-1">If element value matches then fill the value otherwise skip the field <a class="header-anchor" href="#if-element-value-matches-then-fill-the-value-otherwise-skip-the-field" aria-label="Permalink to “If element value matches then fill the value otherwise skip the field”">​</a></h3><p>Conditionally executes the field action based on whether the current DOM value matches a target pattern.</p><ul><li><strong>Value Match</strong>: Executes the field action if the element&#39;s existing value matches your criteria.</li><li><strong>Value Mismatch</strong>: Skips the field if values do not match.</li><li><strong>Empty Check</strong>: Use <code>&#39;&#39;</code> (two single quotes) to specifically check for empty or unpopulated elements.</li></ul><img src="/image/field-settings-08.png" alt="Element Value Matching Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h3 id="skip-field-action-if-condition-is-true" tabindex="-1">Skip field action if condition is true <a class="header-anchor" href="#skip-field-action-if-condition-is-true" aria-label="Permalink to “Skip field action if condition is true”">​</a></h3><p>Evaluates multi-attribute rules on elements to skip field actions dynamically.</p><ul><li><strong>Element Visible / Not Visible</strong></li><li><strong>Element Exists / Not Exists</strong></li><li><strong>Element Value / Text Matched</strong></li><li><strong>Element Attribute / HTML Matched</strong></li><li><strong>Image File Name Matched</strong></li></ul><img src="/image/field-settings-09.png" alt="Advanced Skip Conditions" style="max-width:500px;border-radius:8px;margin:16px 0;"><hr><h3 id="skip-field-action-if-given-field-value-matches" tabindex="-1">Skip field action if given field value matches <a class="header-anchor" href="#skip-field-action-if-given-field-value-matches" aria-label="Permalink to “Skip field action if given field value matches”">​</a></h3><p>Checks the spreadsheet row value of a <strong>different</strong> field and skips this field if that value matches specified criteria.</p><ul><li><strong>Field Reference</strong>: Choose another field in the form to evaluate.</li><li><strong>Value List</strong>: Comma-separated or line-separated values that trigger skipping.</li><li><strong>Example</strong>: Skip the &quot;Passport Number&quot; field if the &quot;Has Passport?&quot; field is set to <code>&quot;No&quot;</code> or <code>&quot;N&quot;</code>.</li></ul><img src="/image/skip-field-01.png" alt="Field Value Skip Configuration" style="max-width:500px;border-radius:8px;margin:16px 0;"><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>This option evaluates values according to the Excel row data. If you are using dynamic variables or multiple values per row, configure individual field conditions instead.</p></div><hr><h3 id="skip-field-action-if-field-value-matches" tabindex="-1">Skip field action if field value matches <a class="header-anchor" href="#skip-field-action-if-field-value-matches" aria-label="Permalink to “Skip field action if field value matches”">​</a></h3><p>Skips the field if <strong>its own</strong> assigned value matches any item in a configured value list.</p><ul><li><strong>Values List</strong>: Define values that will cause this field to be skipped.</li><li><strong>Convert to Lowercase</strong>: Enable case-insensitive comparison by normalizing strings to lowercase.</li><li><strong>Empty Value Handling</strong>: Use <code>&#39;&#39;</code> to skip the field if its value is blank or empty.</li></ul><hr><h2 id="field-validation-settings" tabindex="-1">Field Validation Settings <a class="header-anchor" href="#field-validation-settings" aria-label="Permalink to “Field Validation Settings”">​</a></h2><h3 id="is-this-field-required" tabindex="-1">Is this field Required <a class="header-anchor" href="#is-this-field-required" aria-label="Permalink to “Is this field Required”">​</a></h3><p>Marks the field as mandatory for form completion.</p><ul><li><strong>Visual Badge</strong>: Displays a red <code>Required</code> badge next to the field in the configuration table.</li><li><strong>Public Key Integration</strong>: Evaluated by the <code>&lt;code v-pre&gt;{FORM-FILLED}&lt;/code&gt;</code> key to verify that all mandatory fields contain data.</li><li><strong>Submission Safeguard</strong>: Prevents premature form submission if mandatory fields fail to fill.</li></ul><hr><h2 id="response-action-settings" tabindex="-1">Response Action Settings <a class="header-anchor" href="#response-action-settings" aria-label="Permalink to “Response Action Settings”">​</a></h2><p>Configure automated follow-up actions based on execution outcomes:</p><h3 id="field-success-response-action" tabindex="-1">Field Success Response Action <a class="header-anchor" href="#field-success-response-action" aria-label="Permalink to “Field Success Response Action”">​</a></h3><p>Executes a predefined action when this field completes successfully (e.g., clicking a submit button, executing a segment, or setting local data).</p><p>See <a href="/documentation/form-fields/field-response-action.html#field-success-response-action">Field Response Action Guide</a>.</p><h3 id="field-error-response-action" tabindex="-1">Field Error Response Action <a class="header-anchor" href="#field-error-response-action" aria-label="Permalink to “Field Error Response Action”">​</a></h3><p>Executes fallback recovery routines if the field encounters an error (e.g., reloading the page or triggering alert notifications).</p><p>See <a href="/documentation/form-fields/field-response-action.html#field-error-response-action">Field Response Action Guide</a>.</p><h3 id="field-skip-response-action" tabindex="-1">Field Skip Response Action <a class="header-anchor" href="#field-skip-response-action" aria-label="Permalink to “Field Skip Response Action”">​</a></h3><p>Executes specific fallback routines whenever this field is skipped by condition rules.</p><p>See <a href="/documentation/form-fields/field-response-action.html#field-skip-response-action">Field Response Action Guide</a>.</p><hr><h2 id="automation-control-settings" tabindex="-1">Automation Control Settings <a class="header-anchor" href="#automation-control-settings" aria-label="Permalink to “Automation Control Settings”">​</a></h2><h3 id="if-error-response-is-coming-in-the-field-then-stop-filler" tabindex="-1">If error response is coming in the field then stop filler <a class="header-anchor" href="#if-error-response-is-coming-in-the-field-then-stop-filler" aria-label="Permalink to “If error response is coming in the field then stop filler”">​</a></h3><p>Immediately stops form filling for the active site if this field triggers an error response.</p><ul><li><strong>Critical Fields</strong>: Prevents cascading failures when a mandatory field (such as a captcha or account ID) fails.</li><li><strong>Safe Halting</strong>: Halts execution cleanly so you can resolve the issue manually.</li></ul><hr><h3 id="if-success-response-is-coming-in-the-field-then-stop-filler" tabindex="-1">If success response is coming in the field then stop filler <a class="header-anchor" href="#if-success-response-is-coming-in-the-field-then-stop-filler" aria-label="Permalink to “If success response is coming in the field then stop filler”">​</a></h3><p>Stops the automation process as soon as this field finishes successfully.</p><ul><li><strong>Single-Action Automation</strong>: Useful when a form only requires completing a single verification or query step.</li><li><strong>Stop on Milestone</strong>: Safely halts automation after reaching a final confirmation step.</li></ul><hr><h2 id="advanced-settings" tabindex="-1">Advanced Settings <a class="header-anchor" href="#advanced-settings" aria-label="Permalink to “Advanced Settings”">​</a></h2><h3 id="search-strings-and-execute-field-action" tabindex="-1">Search Strings and Execute Field Action <a class="header-anchor" href="#search-strings-and-execute-field-action" aria-label="Permalink to “Search Strings and Execute Field Action”">​</a></h3><p>Scans the web page for target strings or regex patterns and triggers field execution when found.</p><ul><li><strong>Text Search</strong>: Locates specific status messages, validation banners, or text tokens.</li><li><strong>Pattern Matching</strong>: Supports exact matching and regular expressions.</li></ul><p>Learn more in <a href="/documentation/field-options/search-and-action.html">Search Strings and Execute Field Action</a>.</p><hr><h3 id="execute-action-on-fields-like-row-type" tabindex="-1">Execute Action on fields like Row Type <a class="header-anchor" href="#execute-action-on-fields-like-row-type" aria-label="Permalink to “Execute Action on fields like Row Type”">​</a></h3><p>Applies bulk field operations across multiple fields configured with the same row structure.</p><ul><li><strong>Bulk Consistency</strong>: Ensures uniform timing and event handling across tabular inputs.</li><li><strong>Fast Configuration</strong>: Reduces repetitive manual configuration for grid-based forms.</li></ul><hr><h3 id="if-this-field-is-being-used-in-a-loop-and-the-field-has-multiple-elements" tabindex="-1">If this field is being used in a loop and the field has multiple elements <a class="header-anchor" href="#if-this-field-is-being-used-in-a-loop-and-the-field-has-multiple-elements" aria-label="Permalink to “If this field is being used in a loop and the field has multiple elements”">​</a></h3><p>Manages multiple matching DOM elements when executed inside automated loops.</p><ul><li><strong>Index Targeting</strong>: Binds the target element index to the active loop counter (<code>index</code>).</li><li><strong>Dynamic Element Collections</strong>: Reliably populates repeating table rows, dynamic lists, or repeated field sets.</li></ul><hr><h3 id="do-not-fill-the-status-color-element-of-this-field" tabindex="-1">Do not fill the Status Color, element of this field <a class="header-anchor" href="#do-not-fill-the-status-color-element-of-this-field" aria-label="Permalink to “Do not fill the Status Color, element of this field”">​</a></h3><p>Disables the visual status outline and background highlight normally added to elements by the extension upon completion.</p><ul><li><strong>Visual Preservation</strong>: Maintains original element styling and border presentation.</li><li><strong>Screenshot Readiness</strong>: Prevents green/yellow status outlines from appearing in form captures.</li></ul><hr><h3 id="ignore-this-field-details-in-the-excel-template" tabindex="-1">Ignore this field details in the Excel Template <a class="header-anchor" href="#ignore-this-field-details-in-the-excel-template" aria-label="Permalink to “Ignore this field details in the Excel Template”">​</a></h3><p>Excludes this field from generated <code>.xlsx</code> templates downloaded via the <strong>Excel Template</strong> tab.</p><ul><li><strong>Static Fields</strong>: Keep button clicks, triggers, and static fields out of data spreadsheets.</li><li><strong>Cleaner Templates</strong>: Generates <code>.xlsx</code> files containing only the actual input columns required for data entry.</li></ul><hr><h2 id="timing-position-settings" tabindex="-1">Timing &amp; Position Settings <a class="header-anchor" href="#timing-position-settings" aria-label="Permalink to “Timing &amp; Position Settings”">​</a></h2><h3 id="delay-time-before-this-field-is-run" tabindex="-1">Delay Time Before this field is Run <a class="header-anchor" href="#delay-time-before-this-field-is-run" aria-label="Permalink to “Delay Time Before this field is Run”">​</a></h3><p>Specifies a waiting delay (in milliseconds) before the extension interacts with this field.</p><ul><li><strong>Fixed Delay</strong>: Enter a numerical timeout in milliseconds (e.g., <code>500</code>).</li><li><strong>Dynamic / Randomized Delay</strong>: Use randomized template variables wrapped in double curly braces:</li></ul>`,158),t(`div`,null,[t(`div`,{class:`language-text`},[t(`button`,{title:`Copy Code`,class:`copy`}),t(`span`,{class:`lang`},`text`),t(`pre`,{class:`shiki shiki-themes github-light github-dark`,style:{"--shiki-light":`#24292e`,"--shiki-dark":`#e1e4e8`,"--shiki-light-bg":`#fff`,"--shiki-dark-bg":`#24292e`},tabindex:`0`,dir:`ltr`,"v-pre":``},[t(`code`,null,[t(`span`,{class:`line`},[t(`span`,null,`{{random.integer[500][1500]}}`)])])])])],-1),t(`hr`,null,null,-1),t(`h3`,{id:`delay-time-after-this-field-is-run`,tabindex:`-1`},[i(`Delay Time After this field is Run `),t(`a`,{class:`header-anchor`,href:`#delay-time-after-this-field-is-run`,"aria-label":`Permalink to “Delay Time After this field is Run”`},`​`)],-1),t(`p`,null,`Specifies a waiting delay (in milliseconds) after the field action finishes before moving to the next field.`,-1),t(`ul`,null,[t(`li`,null,[t(`strong`,null,`Asynchronous Processing`),i(`: Gives web applications time to process client-side calculations, trigger animations, or update dependent controls.`)]),t(`li`,null,[t(`strong`,null,`Dynamic / Randomized Delay`),i(`:`)])],-1),t(`div`,null,[t(`div`,{class:`language-text`},[t(`button`,{title:`Copy Code`,class:`copy`}),t(`span`,{class:`lang`},`text`),t(`pre`,{class:`shiki shiki-themes github-light github-dark`,style:{"--shiki-light":`#24292e`,"--shiki-dark":`#e1e4e8`,"--shiki-light-bg":`#fff`,"--shiki-dark-bg":`#24292e`},tabindex:`0`,dir:`ltr`,"v-pre":``},[t(`code`,null,[t(`span`,{class:`line`},[t(`span`,null,`{{random.integer[1000][2000]}}`)])])])])],-1),a(`<hr><h3 id="position-of-field" tabindex="-1">Position of Field <a class="header-anchor" href="#position-of-field" aria-label="Permalink to “Position of Field”">​</a></h3><p>Configures the execution priority and ordering position of the field within the form runner.</p><ul><li><strong>Select Position of Field</strong>: Choose the field&#39;s position to place it earlier or later in the execution sequence without recreating the field.</li><li><strong>Sequence Management</strong>: Ensures prerequisite fields (such as agreement checkboxes or authentication triggers) execute in the required order.</li></ul><hr><h2 id="specialized-settings" tabindex="-1">Specialized Settings <a class="header-anchor" href="#specialized-settings" aria-label="Permalink to “Specialized Settings”">​</a></h2><h3 id="if-form-is-aspx-then-remove-input-behavior" tabindex="-1">If form is ASPX, remove the input behavior <a class="header-anchor" href="#if-form-is-aspx-then-remove-input-behavior" aria-label="Permalink to “If form is ASPX, remove the input behavior”">​</a></h3><p>Special compatibility mode for ASP.NET (<code>.aspx</code>) web forms.</p><ul><li><strong>ASP.NET PostBack Handling</strong>: Removes intrusive browser input behaviors and default change event handling that can cause premature form postbacks or page resets.</li><li><strong>Compatibility Assurance</strong>: Ensures smooth and reliable data entry on legacy enterprise ASPX systems.</li></ul><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ol><li><strong>Test Dynamic Delays</strong>: Use realistic before/after delays for AJAX and SPA applications to avoid race conditions.</li><li><strong>Leverage Text Editor Mode</strong>: For rich text boxes or WYSIWYG editors, enable <strong>Text editor mode</strong> with random pauses for optimal compatibility.</li><li><strong>Use Child Selectors for Nested UI</strong>: When targeting inputs inside modern web components or tables, use <strong>Selector Query of Element&#39;s Child Element</strong>.</li><li><strong>Clean Excel Templates</strong>: Enable <strong>Ignore this field details in the Excel Template</strong> for click triggers and navigation fields.</li></ol><hr><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to “Next Steps”">​</a></h2><ul><li><img src="/svg/database.svg" class="doc-icon"> <a href="/documentation/form-fields/field-types.html">Field Types</a> - Explore supported field types</li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/form-fields/field-response-action.html">Field Response Actions</a> - Configure success and error behaviors</li><li><img src="/svg/code.svg" class="doc-icon"> <a href="/documentation/variable.html">Variables Reference</a> - Use dynamic random and time variables</li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/site/site-settings.html">Site Settings</a> - Configure site-wide defaults and overrides</li></ul>`,15)]])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};